/bin/bash -lc "python3 - <<'PY'
import urllib.request
for url in ('https://developers.openai.com/api-reference/responses/create','https://platform.openai.com/docs/api-reference/responses/create'):
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            body = response.read().decode('utf-8', 'replace')
            print(url, response.status, len(body), body[:200].replace('\\n',' '))
    except Exception as exc:
        print(url, repr(exc))
PY"

